package com.sloth.client.screen;
import com.sloth.client.studio.CosmicSuite;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.EditBox;import net.minecraft.client.gui.screens.ChatScreen;import net.minecraft.client.gui.screens.Screen;import net.minecraft.network.chat.Component;
public final class CosmicSuiteScreen extends MenuFrame{
 private int index;private EditBox note;private String status="Visible messages and manual notes only.";public CosmicSuiteScreen(Screen parent){this(parent,0);}private CosmicSuiteScreen(Screen parent,int index){super(parent,"Cosmic Companion");this.index=Math.floorMod(index,CosmicSuite.Tool.values().length);}protected Tab tab(){return Tab.STUDIO;}protected String railPage(){return "Gameplay";}protected String workspaceTitle(){return "COSMIC COMPANION";}protected String workspaceSubtitle(){return CosmicSuite.Tool.values().length+" focused workspaces for Cosmic Prisons.";}
 private CosmicSuite.Tool tool(){return CosmicSuite.Tool.values()[index];}
 protected void initContent(){var t=tool();note=new EditBox(font,contentX,contentY+28,contentW,42,Component.literal("Local notes and checklist"));note.setMaxLength(600);note.setValue(CosmicSuite.note(t));note.setHint(Component.literal("Local notes, checklist, prices, routes or strategy"));addRenderableWidget(note);int gap=6,w=(contentW-gap*5)/6,y=contentY+78;button(contentX,y,w,21,"-10",b->minecraft.setScreen(new CosmicSuiteScreen(parent,index-10)));button(contentX+w+gap,y,w,21,"Previous",b->minecraft.setScreen(new CosmicSuiteScreen(parent,index-1)));button(contentX+(w+gap)*2,y,w,21,"Next",b->minecraft.setScreen(new CosmicSuiteScreen(parent,index+1)));button(contentX+(w+gap)*3,y,w,21,"+10",b->minecraft.setScreen(new CosmicSuiteScreen(parent,index+10)));primary(contentX+(w+gap)*4,y,w,21,"Save",b->{CosmicSuite.note(t,note.getValue());status="Saved locally.";});button(contentX+(w+gap)*5,y,w,21,"Count +1",b->{CosmicSuite.bump(t);status="Counter updated.";});int by=contentY+contentH-24;button(contentX,by,104,21,"Reset count",b->{CosmicSuite.reset(t);status="Counter reset.";});button(contentX+112,by,116,21,"Draft command",b->minecraft.setScreen(new ChatScreen(t.command,false)));primary(contentX+contentW-78,by,78,21,"Done",b->onClose());}
 protected void renderContentBackground(GuiGraphics g,int mx,int my){Ui.rounded(g,contentX,contentY+108,contentW,contentH-140,0x70201A27);Ui.roundedOutline(g,contentX,contentY+108,contentW,contentH-140,Ui.LINE);}
 protected void renderContent(GuiGraphics g,int mx,int my,float pt){var t=tool();g.drawString(font,(index+1)+" / "+CosmicSuite.Tool.values().length+"  "+t.title.toUpperCase(),contentX,contentY+8,Ui.ACCENT_SOFT,false);int y=contentY+119;g.drawString(font,"OBSERVED COUNT  "+CosmicSuite.count(t),contentX+12,y,Ui.TEXT,false);g.drawString(font,Ui.ellipsize(font,CosmicSuite.status(t),contentW-24),contentX+12,y+18,Ui.MUTED,false);if(t==CosmicSuite.Tool.REPORTS)g.drawString(font,Ui.ellipsize(font,CosmicSuite.report(),contentW-24),contentX+12,y+36,Ui.TEXT,false);else g.drawString(font,"Command draft  "+t.command,contentX+12,y+36,Ui.MUTED,false);g.drawString(font,Ui.ellipsize(font,status,contentW-250),contentX+236,contentY+contentH-18,Ui.MUTED,false);}
}
